    fun getTopics(): List<Topic> = topics

    private fun localized(value: String): Map<String, String> {
        val values = value.split("|")
        require(values.size == LANGUAGES.size)
        return LANGUAGES.zip(values).toMap()
    }

    private fun topic(id: Int, texts: String, vararg questions: Question) =
        Topic(id = id, texts = localized(texts), questions = questions.toList())

    private fun q(id: Int, rightAnswerId: Int, texts: String, vararg answers: String) =
        Question(id = id, texts = localized(texts), rightAnswerId = rightAnswerId,
            answers = answers.mapIndexed { index, answer -> Answer(index + 1, localized(answer)) })

    private companion object {
        val LANGUAGES = listOf("en", "de", "es", "fr", "hi", "id", "pt", "ar")
    }
}
